SELECT count(*) FILTER (WHERE n.nspname='public' AND NOT p.prosecdef) public_invokers,count(*) FILTER (WHERE n.nspname='aurea_manager_rpc' AND p.prosecdef) private_definers,has_function_privilege('service_role','public.aurea_employee_submit(text,jsonb)','EXECUTE') legacy_service_access FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','aurea_manager_rpc') AND p.proname IN ('aurea_manager_actions','aurea_manager_cycles','aurea_manager_save_action','aurea_manager_summary','aurea_my_companies');